#include "bsp/native_dword_vector_insertn_owner.hpp"
#include "bsp/native_dword_vector_outer_tidy.hpp"
#include "bsp/native_word_vector_tidy.hpp"
#include "bsp/native_singleton_vector_allocation.hpp"
#include <array>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <set>
#include <stdexcept>
#include <vector>

struct Header { std::uint32_t opaque, begin, end, capacity; };
static_assert(sizeof(Header) == 16 && sizeof(void*) == 4);
using Pair = std::array<std::uint32_t, 2>;
static std::uint32_t bits(const void* p) {
    return static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(p));
}
static void* pointer(std::uint32_t p) { return reinterpret_cast<void*>(p); }
static void require(bool value, const char* message) {
    if (!value) throw std::runtime_error(message);
}
static void check(const Header& h, const Header& fill,
    const std::vector<Pair>& expected) {
    require(h.opaque == 0x12345678u, "outer opaque word changed");
    require((h.end - h.begin) / 16u == expected.size(), "wrong logical count");
    require(h.end <= h.capacity, "end exceeds capacity");
    std::set<std::uint32_t> owned;
    auto* rows = static_cast<const Header*>(pointer(h.begin));
    for (std::size_t i = 0; i != expected.size(); ++i) {
        const auto& row = rows[i];
        require(row.begin && row.end == row.begin + 8u &&
            row.capacity == row.end, "wrong inner extent");
        require(row.begin != fill.begin && owned.insert(row.begin).second,
            "backing ownership aliased");
        const auto* words = static_cast<const std::uint32_t*>(pointer(row.begin));
        require(words[0] == expected[i][0] && words[1] == expected[i][1],
            "wrong logical values/order");
    }
}
int main() {
    try {
        auto* value = static_cast<std::uint32_t*>(std::malloc(8));
        require(value != nullptr, "fixture allocation failed");
        value[0] = 77; value[1] = 88;
        Header fill{0xabcdef01u, bits(value), bits(value) + 8u, bits(value) + 8u};
        Header h{0x12345678u, 0, 0, 0};
        std::vector<Pair> expected;
        auto insert = [&](std::size_t index, std::uint32_t count) {
            bsp::insert_native_dword_vector_header_count_00698400(
                &h, 0, 0, pointer(h.begin + static_cast<std::uint32_t>(index * 16u)),
                count, &fill);
        };
        insert(0, 0); check(h, fill, expected);
        require(h.begin == 0 && h.capacity == 0, "zero insertion allocated outer backing");
        insert(0, 2); expected = {{77,88},{77,88}}; check(h, fill, expected);
        require(h.capacity - h.begin == 32u, "first growth capacity differs");

        // Supply spare raw header backing, independently of the insertion code.
        auto* spare = std::realloc(pointer(h.begin), 8u * sizeof(Header));
        require(spare != nullptr, "fixture reserve failed");
        h.begin = bits(spare); h.end = h.begin + 32u; h.capacity = h.begin + 128u;
        insert(2, 1); expected.push_back({77,88}); check(h, fill, expected);
        value[0] = 99; value[1] = 100;
        insert(1, 1); expected = {{77,88},{99,100},{77,88},{77,88}};
        check(h, fill, expected);
        value[0] = 55; value[1] = 66;
        insert(3, 3); expected = {{77,88},{99,100},{77,88},{55,66},{55,66},{55,66},{77,88}};
        check(h, fill, expected);
        value[0] = 33; value[1] = 44;
        insert(2, 2); expected = {{77,88},{99,100},{33,44},{33,44},{77,88},{55,66},{55,66},{55,66},{77,88}};
        check(h, fill, expected);
        require(h.capacity - h.begin == 192u, "1.5x growth capacity differs");
        insert(4, 0); check(h, fill, expected);

        const Header before = h;
        bool actual_error = false;
        try { insert(0, 0x10000000u); }
        catch (const bsp::NativeSingletonVectorLengthError&) { actual_error = true; }
        require(actual_error, "wrong owning length-error boundary");
        require(h.begin == before.begin && h.end == before.end &&
            h.capacity == before.capacity, "overflow changed public extent");
        check(h, fill, expected);
        require(value[0] == 33 && value[1] == 44 && fill.opaque == 0xabcdef01u,
            "fill storage was modified");
        bsp::tidy_native_dword_vector_outer_storage_004dc1c0(&h, 0);
        bsp::tidy_native_word_vector_storage_004cdce0(&fill);
        require(h.begin == 0 && h.end == 0 && h.capacity == 0 && fill.begin == 0,
            "actual cleanup did not clear storage");
        std::puts("PASS: one Source fixture: zero, growth, spare short/long, values/ownership, actual owning length error, cleanup");
        return 0;
    } catch (const std::exception& e) {
        std::fprintf(stderr, "FAIL: %s\n", e.what()); return 1;
    } catch (...) {
        std::fputs("FAIL: unexpected exception\n", stderr); return 2;
    }
}
